import { renderFieldPotionTreatment } from './field-treatment-ui.js';
import { INN_GOODS } from './hospitality-v36.js';
import { ownedGear, getGearItem, gearBonuses, gearScore, projectedEquipment, gearOrganizer } from './gear.js';
import { EQUIPMENT_SLOTS, SLOT_NAMES, itemScore, setProgress } from './gear-loot.js';
import { equipmentComparator } from './gear-comparison.js';
import { renderEquipmentComparison, bonusText } from './equipment-comparison-ui.js';
import { equipmentActionReason, consumableReason, fieldPotionQuote, getActions } from './engine.js';
import { renderAvatar } from './avatar.js';
import { renderGearArt as gearIllustration, renderCarriedArt } from './item-art.js';
import { CAMP_KITS } from './travel-energy.js';
import { renderGearOrganizer } from './gear-organizer-ui.js';
export function renderGearArt(item,e=String){return gearIllustration(item,e);}
const title=s=>String(s).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const ranks={common:0,uncommon:1,rare:2,epic:3,legendary:4};
export function inventoryEntries(s){
 const equipped=projectedEquipment(s),rows=ownedGear(s).map(item=>({id:'gear:'+item.id,item,kind:'equipment',name:item.name,slot:item.slot,quality:item.quality||'common',score:itemScore(item),value:item.price||0,quantity:1,favorite:gearOrganizer(s).favorites.includes(item.id),equipped:equipped[item.slot]===item.id}));
 for(const g of INN_GOODS)if(s.hospitality?.bag[g.id]>0)rows.push({id:'supply:'+g.id,kind:'supplies',name:g.name,quantity:s.hospitality.bag[g.id],value:g.price,description:g.description});
 for(const [id,n] of Object.entries(s.equipment?.materials||{}))if(n>0)rows.push({id:'material:'+id,kind:'materials',name:title(id),quantity:n,value:0,description:'Materials carried for equipment designs and workshop projects.'});
 if(s.flags?.herbs>0)rows.push({id:'supply:herbs',kind:'supplies',name:'Medicinal Herbs',quantity:s.flags.herbs,value:0,description:'Gathered herbs for available remedies and care.'});
 if(s.hero.potions>0)rows.push({id:'supply:potions',kind:'supplies',name:'Healing Potions',quantity:s.hero.potions,value:0});
 for(const pack of s.trail?.kits||[]){const kit=CAMP_KITS.find(k=>k.id===pack.kind);rows.push({id:'camp:'+pack.id,kind:'supplies',name:kit.name,quantity:1,value:0,description:pack.remaining+'/'+kit.nights+' sheltered nights remain. Make camp from the travelling screen or Recovery while on the trail. Each sheltered night restores Focus and Health and reduces Stress.'});}
 if(s.adventuring?.rations>0)rows.push({id:'supply:rations',kind:'supplies',name:'Expedition Rations',quantity:s.adventuring.rations,value:0});
 for(const l of s.adventuring?.loot||[])rows.push({id:'loot:'+l.id,kind:'loot',name:l.name,quantity:1,value:l.value||0,description:l.stolen?'Stolen goods retain their witnessed consequences. '+(l.ownerName?'Original owner: '+l.ownerName+'.':'Original owner unknown.')+' Taken at '+(s.world.locations.find(p=>p.id===l.source)?.name||l.source)+' on day '+l.day+'.':'Recovered during an actual expedition.'});
 for(const p of s.rpg?.properties||[])if(p.soldDay===null&&p.returnedDay===null)rows.push({id:'property:'+p.id,kind:'loot',name:p.label,quantity:1,value:0,description:`Acquired on day ${p.acquiredDay}. Its source and owner remain recorded.`});
 return rows;
}
export function inventoryPage(s,{query='',filter='all',category='all',sort='type',selectedId=null,favoritesOnly=false}={}){
 const all=inventoryEntries(s),q=String(query).trim().toLowerCase();let rows=all.filter(r=>(!favoritesOnly||r.favorite)&&(filter==='all'||r.slot===filter)&&(category==='all'||r.kind===category)&&(!q||(r.name+' '+(r.slot||'')+' '+r.kind).toLowerCase().includes(q)));
 rows.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='value'?b.value-a.value||a.name.localeCompare(b.name):sort==='rarity'?(ranks[b.quality]||0)-(ranks[a.quality]||0)||a.name.localeCompare(b.name):sort==='score'?(b.score||0)-(a.score||0)||a.name.localeCompare(b.name):(a.slot||a.kind).localeCompare(b.slot||b.kind)||a.name.localeCompare(b.name));
 const selected=rows.find(r=>r.id===selectedId)||rows[0]||null;return {all,rows,selected};
}
export function renderPlayerInventory(s,ui,options={}){
 const {e,button}=ui,v=inventoryPage(s,options),eq=projectedEquipment(s),reason=equipmentActionReason(s),bonuses=gearBonuses(s),selected=v.selected;
 const slotIcons={weapon:'⚔',offhand:'◈',head:'♜',armor:'▣',hands:'✥',feet:'♟',cloak:'◇',belt:'═',trinket:'✦',ring:'○'};
 const order=['head','armor','hands','feet','cloak','trinket','ring','belt','weapon','offhand'];
 const doll=`<section class="inventory-character" aria-label="Equipped Character"><header><h2>${e(s.hero.name)}</h2><p>Level ${s.hero.level} · ${e(s.hero.specialization||(s.hero.path==='unformed'?s.hero.profession:title(s.hero.path)))}</p></header><div class="inventory-doll"><div class="inventory-portrait">${renderAvatar(s.hero,{size:'hero',age:s.age})}</div>${order.map((slot,i)=>{const item=getGearItem(s,eq[slot]);return `<button type="button" class="inventory-equip-slot rarity-${item?.quality||'common'}" data-op="gear-slot" data-id="${slot}" data-equipment-slot="${slot}" style="grid-column:${i<5?1:3};grid-row:${i%5+1}" aria-label="${e(SLOT_NAMES[slot]+': '+(item?.name||'Empty'))}" title="${e(SLOT_NAMES[slot]+': '+(item?.name||'Empty'))}">${item?renderGearArt(item,e):`<span aria-hidden="true">${slotIcons[slot]}</span>`}<small>${e(SLOT_NAMES[slot])}</small></button>`;}).join('')}</div><dl class="inventory-stat-line"><div><dt>Health</dt><dd>${s.hero.hp}/${s.hero.maxHp}</dd></div><div><dt>Focus</dt><dd>${s.hero.mp}/${s.hero.maxMp}</dd></div><div><dt>Equipment Score</dt><dd>${gearScore(s)}</dd></div></dl><div class="inventory-bonuses">${Object.entries(bonuses).filter(([,n])=>n).map(([k,n])=>`<span>${e(title(k))} ${n>0?'+':''}${n}</span>`).join('')||'<span>No Equipment Bonuses</span>'}</div>${setProgress(ownedGear(s).filter(i=>Object.values(eq).includes(i.id))).map(set=>`<details class="inventory-set"><summary>${e(set.name)} · ${set.count} Pieces</summary>${set.thresholds.map(t=>`<p>${t.count} pieces · ${t.active?'Active':'Inactive'} · ${e(bonusText(t.bonuses))}</p>`).join('')}</details>`).join('')}${renderGearOrganizer(s,ui,{selectedId:options.presetId,reason})}</section>`;
 const categories=[['all','All Items'],['equipment','Equipment'],['supplies','Supplies'],['materials','Materials'],['loot','Loot']];
 const toolbar=`<form id="inventory-search" class="inventory-toolbar"><label class="sr-only" for="inventory-query">Search Inventory</label><input id="inventory-query" name="query" type="search" value="${e(options.query||'')}" placeholder="Search Inventory"><button class="button secondary small" type="submit">Search</button><label>Sort<select id="inventory-sort" name="sort">${[['type','Type'],['name','Name'],['rarity','Rarity'],['score','Score'],['value','Value']].map(([id,label])=>`<option value="${id}" ${(options.sort||'type')===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Slot<select id="inventory-slot" name="slot">${[['all','All Slots'],...EQUIPMENT_SLOTS.map(slot=>[slot,SLOT_NAMES[slot]])].map(([id,label])=>`<option value="${id}" ${(options.filter||'all')===id?'selected':''}>${label}</option>`).join('')}</select></label></form><nav class="inventory-categories" aria-label="Inventory Categories">${categories.map(([id,label])=>button(label,'inventory-category',id,'ghost small',false,(options.category||'all')===id)).join('')}${button('★ Favorites','inventory-favorites','','ghost small',false,Boolean(options.favoritesOnly))}</nav>`;
 const cells=v.rows.map(r=>`<button type="button" class="inventory-cell rarity-${r.quality||'common'} ${r.id===selected?.id?'selected':''}" data-op="inventory-item" data-id="${e(r.id)}" data-item-id="${e(r.item?.id||r.id)}" ${r.item?`draggable="true" data-draggable-gear="${e(r.item.id)}"`:""} aria-pressed="${r.id===selected?.id}" aria-label="${e(r.name+(r.equipped?' · Equipped':'')+(r.favorite?' · Favorite':'')+(r.quantity>1?' · '+r.quantity:''))}" title="${e(r.name)}">${renderCarriedArt(r,e)}${r.quantity>1?`<small class="item-quantity">${r.quantity}</small>`:''}${r.equipped?'<span class="item-equipped" aria-label="Equipped">◆</span>':''}${r.favorite?'<span class="item-favorite" aria-hidden="true">★</span>':''}</button>`).join('');
 const empty=Array.from({length:Math.max(0,24-v.rows.length)},()=>'<span class="inventory-cell empty" aria-hidden="true"></span>').join('');
 let detail='<section class="inventory-detail"><h2 id="inventory-item-heading" tabindex="-1">Your Backpack</h2><p>Select an item to inspect it. Drag equipment into a matching slot, or choose Equip.</p></section>';
 if(selected){const r=selected,i=r.item,valuable=r.id.startsWith('loot:')?s.adventuring.loot.find(l=>l.id===r.id.slice(5)):null,propertyActions=i?.stolen?getActions(s).filter(a=>a.id==='realm_sellgear_'+i.id||a.id==='realm_returngear_'+i.id):valuable?.stolen?getActions(s).filter(a=>a.id==='realm_sellloot_'+valuable.id&&!a.disabledReason):[],comparison=i?equipmentComparator(s)(r.equipped?'unequip_'+i.slot:i.id):null;detail=`<section class="inventory-detail" data-inventory-selected="${e(r.id)}"><div class="section-heading"><h2 id="inventory-item-heading" tabindex="-1">${e(r.name)}</h2>${i?`<span class="badge">${e(title(r.quality))} · ${e(SLOT_NAMES[r.slot])}</span>`:`<span class="badge">${r.quantity} Carried</span>`}</div>${renderCarriedArt(r,e)}<p>${e(i?.description||r.description||(r.id==='supply:potions'?'Use one to restore up to 30 Health to yourself or a living active companion. Potions do not cure illnesses or revive the downed.':'Provisions for actual descents and camps.'))}</p>${i?.stolen?`<p class="small-copy inventory-provenance">Stolen property · ${e(i.provenance.ownerName?'Original owner: '+i.provenance.ownerName:'Original owner unknown')}. Taken at ${e(s.world.locations.find(p=>p.id===i.source)?.name||i.source)} on day ${i.foundDay}. Equipping it does not erase its origin.</p>`:''}${i?`<div class="inventory-bonuses">${Object.entries(i.bonuses).filter(([,n])=>n).map(([k,n])=>`<span>${e(title(k))} ${n>0?'+':''}${n}</span>`).join('')}</div><p class="small-copy">Score ${r.score} · Value ${r.value} Gold${r.equipped?' · Equipped':''}</p><div class="inventory-item-actions">${button(r.equipped?'Unequip':'Equip','equip',r.equipped?'unequip_'+i.slot:i.id,'primary',Boolean(reason))}${button(r.favorite?'★ Unfavorite':'☆ Favorite','gear-favorite',i.id,'secondary',false,Boolean(r.favorite))}${reason?`<span class="disabled-reason">${e(reason)}</span>`:''}</div><p class="small-copy">Favorites are bookmarks, not sale locks. You can still deliberately sell a favorited piece.</p>${propertyActions.length?`<div class="inventory-property-actions">${propertyActions.map(a=>`<p>${e(a.description)}</p>${button(a.label,'activity',a.id,'secondary',Boolean(a.disabledReason))}${a.disabledReason?`<p class="disabled-reason">${e(a.disabledReason)}</p>`:''}`).join('')}</div>`:''}<details class="inventory-comparison"><summary>Equipment Changes</summary>${renderEquipmentComparison(comparison,ui)}</details>`:r.id==='supply:potions'?`${renderFieldPotionTreatment(fieldPotionQuote(s),ui,{hero:true})}${(s.companions||[]).some(c=>c.recruited)?`<section class="field-party-treatment" aria-label="Choose a companion for field treatment"><h3>Treat a traveling companion</h3><p class="small-copy">Choose the named person to use one potion. Living, available active travelers only. Potions do not cure illness or stabilize the downed.</p>${s.companions.filter(c=>c.recruited).map(c=>renderFieldPotionTreatment(fieldPotionQuote(s,c.id),ui)).join('')}</section>`:''}`:['supply:herbs','supply:meals','supply:ale'].includes(r.id)?`${button(r.id==='supply:potions'?'Drink Potion':r.id==='supply:meals'?'Eat Meal':r.id==='supply:ale'?'Drink Ale':'Prepare Medicinal Herbs','use-consumable',r.id.split(':')[1],'primary',Boolean(consumableReason(s,r.id.split(':')[1])))}${consumableReason(s,r.id.split(':')[1])?`<p class="disabled-reason">${e(consumableReason(s,r.id.split(':')[1]))}</p>`:''}`:r.kind==='materials'?'<p class="small-copy">Visit a craftsperson in a settlement to use these materials.</p>':valuable?.stolen?`<p class="small-copy">Valuation ${r.value} Gold, not cash. Selling does not erase earlier evidence.</p>${!propertyActions.length?'<p class="small-copy">Visit an open Market for a current buyer and sale offer.</p>':''}${propertyActions.map(a=>`<p>${e(a.description)}</p>${button(a.label,'activity',a.id,'secondary',Boolean(a.disabledReason))}${a.disabledReason?`<p class="disabled-reason">${e(a.disabledReason)}</p>`:''}`).join('')}`:''}</section>`;}
 return `<div class="inventory-workspace" data-pack-pane="inventory"><header class="inventory-heading"><div><span class="eyebrow">WHAT YOU CARRY</span><h1>Inventory</h1></div><span class="inventory-gold">◈ ${s.hero.gold} Gold</span></header><div class="inventory-layout">${doll}<section class="inventory-backpack" aria-label="Backpack">${toolbar}<p class="small-copy" data-view-results>${v.rows.length} ${v.rows.length===1?'item':'items'} shown · ${v.all.length} carried ${v.all.length===1?'entry':'entries'}.</p><div class="inventory-grid" role="group" aria-label="Carried Items">${cells}${empty}</div>${!v.rows.length?'<p class="inventory-empty">No carried items match this view.</p>':''}${detail}</section></div></div>`;
}
